<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Services\AuditService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Hash;
class ProfileController extends Controller { public function edit(){return view('admin.profile');} public function update(Request $r,AuditService $audit){$u=$r->user();$before=$u->only('name','email');$data=$r->validate(['name'=>'required|string|max:100','email'=>'required|email|max:255|unique:users,email,'.$u->id]);$u->update($data);$audit->record('profile.updated',$u,$before,$data);return back()->with('status','個人資料已更新。');} public function password(Request $r,AuditService $audit){$data=$r->validate(['current_password'=>'required|current_password','password'=>'required|confirmed|min:10']);$r->user()->update(['password'=>Hash::make($data['password']),'remember_token'=>\Illuminate\Support\Str::random(60)]);$audit->record('profile.password_updated',$r->user());return back()->with('status','密碼已更新。');}}
